INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3801, 'Numbers 14:15', 'Numbers', 14, 15, '&nbsp;اوس کۀ تۀ خپل ټول خلق ووژنې، نو چې کومو قومونو ستا په حقله اورېدلى دى نو هغوئ به ووائى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3802, 'Numbers 14:16', 'Numbers', 14, 16, '&nbsp;چې تا خپل خلق په صحرا کښې ووژل ځکه چې ستا طاقت نۀ وو چې هغوئ هغه مُلک له بوځې چې تا د ورکولو وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3803, 'Numbers 14:17', 'Numbers', 14, 17, '&nbsp;نو اوس مالِکه خُدايه، زۀ سوال کوم چې مونږ ته خپل طاقت او هغه څۀ وښايه چې تا يې د ورکولو وعده کړې ده، کله چې تا وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3804, 'Numbers 14:18', 'Numbers', 14, 18, '&nbsp;زۀ، مالِک خُدائ په آسانۍ سره نۀ غصه کېږم او زۀ نۀ ختمېدونکې مينه او وفادارى ښايم او زياتے او بغاوت معاف کوم. خو چې څوک ګناه کوى نو د هغوئ د ګناه سزا به د درېم او څلورم نسل پورې جارى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3805, 'Numbers 14:19', 'Numbers', 14, 19, '&nbsp;او اوس مالِکه خُدايه، زۀ تا ته سوال کوم چې د خپلې لوئې او نۀ بدلېدونکې مينې په مطابق د دې خلقو ګناه معاف کړه، هم هغه شان څنګه چې تا هغوئ د مِصر د راوتلو نه تر اوسه پورې معاف کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3806, 'Numbers 14:20', 'Numbers', 14, 20, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”ستا د وېنا په مطابق هغوئ ما معاف کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3807, 'Numbers 14:21', 'Numbers', 14, 21, '&nbsp;خو زما دې په خپل ذات او جلال قسم وى د کوم جلال نه چې ټوله زمکه ډکه ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3808, 'Numbers 14:22', 'Numbers', 14, 22, '&nbsp;چې د دې خلقو نه يو کس به هم هغه مُلک ته داخل نۀ شى. هغوئ زما د حضور جلال او هغه معجزې هم ليدلې دى چې ما په مِصر کښې او په صحرا کښې کړې دى، خو هغوئ بيا بيا زما د صبر امتحان اخستے دے او زما د منلو نه يې اِنکار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3809, 'Numbers 14:23', 'Numbers', 14, 23, '&nbsp;هغوئ به هيڅکله هم هغه مُلک ته دننه نۀ شى د کوم چې ما د هغوئ د پلار نيکۀ سره لوظ کړے دے. هغه هيڅ څوک به هم ورننه نۀ وځى چا چې زما سپکاوے کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3810, 'Numbers 14:24', 'Numbers', 14, 24, '&nbsp;خو زما خِدمتګار کالب د نورو په شان نۀ دے او هغۀ په پوره توګه زما تابعدارى کړې ده، نو زۀ به دے هغه مُلک له راولم کوم چې هغۀ ليدلے دے او هغه مُلک به د هغۀ د اولاد شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3811, 'Numbers 14:25', 'Numbers', 14, 25, '&nbsp;چې په کومو واديانو کښې اوس عماليقيان او کنعانيان اوسيږى. سبا واپس په صحرا کښې د بحرِقُلزم طرف ته روان شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3812, 'Numbers 14:26', 'Numbers', 14, 26, '&nbsp;مالِک خُدائ موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3813, 'Numbers 14:27', 'Numbers', 14, 27, '&nbsp;”دا خراب خلق به تر کومې پورې زما خِلاف شکايت کوى؟ ما دا شکايتونه ډېر زيات اورېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3814, 'Numbers 14:28', 'Numbers', 14, 28, '&nbsp;اوس هغوئ له دا جواب ورکړه، زۀ ژوندے مالِک خُدائ په خپل ذات قسم کوم، چې زۀ به ستاسو دپاره هم هغه شان وکړم څۀ چې تاسو زما په وړاندې وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3815, 'Numbers 14:29', 'Numbers', 14, 29, '&nbsp;تاسو به مړۀ شئ او ستاسو لاشونه به په صحرا کښې خوارۀ وارۀ پراتۀ وى. ځکه چې تاسو زما خِلاف شکايت کړے دے، ستاسو يو کس به هم هغه مُلک ته ورننه نۀ وځى چې عُمر يې د شلو کالو نه زيات وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3816, 'Numbers 14:30', 'Numbers', 14, 30, '&nbsp;ما دا وعده کړې وه چې تاسو به هلته اوسېږئ، خو د کالب او يشوَع نه بغېر به هيڅ څوک هم نۀ ورننه وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3817, 'Numbers 14:31', 'Numbers', 14, 31, '&nbsp;تاسو وئيلى وُو چې ستاسو ماشومان به ونيولے شى، خو زۀ به هغوئ هغه مُلک ته راولم چې تاسو يې مخالفت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3818, 'Numbers 14:32', 'Numbers', 14, 32, '&nbsp;تاسو به دلته په دې صحرا کښې مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3819, 'Numbers 14:33', 'Numbers', 14, 33, '&nbsp;ستاسو بچى به څلوېښت کاله په صحرا کښې سرګردانه ګرځى، ستاسو د نافرمانۍ په وجه به کړيږى، تر دې پورې چې ستاسو آخرى کس هم مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3820, 'Numbers 14:34', 'Numbers', 14, 34, '&nbsp;تاسو ته به څلوېښت کاله د خپلو بدو سزا ملاويږى، د هغه څلوېښتو ورځو د هرې ورځې دپاره به يو کال وى کومې چې تاسو د هغه مُلک په کتلو کښې تېرې کړې دى. تاسو ته به پته ولګى چې زۀ ستاسو خِلاف يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3821, 'Numbers 14:35', 'Numbers', 14, 35, '&nbsp;بې‌شکه چې زۀ به تاسو خرابو خلقو سره داسې وکړم چې زما خِلاف راغونډ شوى يئ. په دې صحرا کښې به تاسو تباه شئ. زۀ، مالِک خُدائ دا وايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3822, 'Numbers 14:38', 'Numbers', 14, 38, '&nbsp;په هغه دولسو جاسوسانو کښې صِرف يشوَع او کالب ژوندى پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3823, 'Numbers 14:39', 'Numbers', 14, 39, '&nbsp;کله چې موسىٰ بنى اِسرائيلو ته هغه څۀ وفرمائيل څۀ چې مالِک خُدائ فرمائيلى وُو، نو هغوئ ډېر غمژن شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3824, 'Numbers 14:40', 'Numbers', 14, 40, '&nbsp;بل سحر وختى هغوئ د غرونو مُلک ته روان شول، هغوئ ووئيل، ”اوس به مونږ هغه مُلک ته لاړ شُو چې د کوم په حقله مالِک خُدائ مونږ ته فرمائيلى دى. مونږ دا منو چې مونږ ګناه کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3825, 'Numbers 14:41', 'Numbers', 14, 41, '&nbsp;خو موسىٰ ورته وفرمائيل، ”نو تاسو ولې د مالِک خُدائ نافرمانى کوئ؟ تاسو به کامياب نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3826, 'Numbers 14:42', 'Numbers', 14, 42, '&nbsp;تاسو مۀ ځئ. مالِک خُدائ ستاسو مل نۀ دے او ستاسو دشمنان به تاسو له شکست درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3827, 'Numbers 14:43', 'Numbers', 14, 43, '&nbsp;کله چې تاسو د عماليقيانو او کنعانيانو سره مخامخ شئ، نو تاسو به په جنګ کښې ووژلے شئ، مالِک خُدائ به ستاسو مل نۀ وى، ځکه چې تاسو د هغۀ د تابعدارۍ نه اِنکار کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3828, 'Numbers 14:44', 'Numbers', 14, 44, '&nbsp;خو هغوئ زړَور روان وُو چې د غرونو مُلک ته وخېژى، اګر چې نۀ د مالِک خُدائ د لوظ صندوق او نۀ موسىٰ د خېمو نه ورسره تلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3829, 'Numbers 14:45', 'Numbers', 14, 45, '&nbsp;بيا عماليقيان او کنعانيان لاندې راغلل کوم چې هلته اوسېدل او هغوئ له يې شکست ورکړو او د حُرمه پورې يې وزغلول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3830, 'Numbers 15:1', 'Numbers', 15, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3831, 'Numbers 15:2', 'Numbers', 15, 2, '&nbsp;چې بنى اِسرائيلو ته دا اصُول وښايه چې په هغه مُلک کښې پرې عمل کوى کوم يې چې هغوئ له ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3832, 'Numbers 15:3', 'Numbers', 15, 3, '&nbsp;يو غوَيے، ګډه، يا يو چېلے مالِک خُدائ ته د سوزېدونکې نذرانې په توګه يا د يوې منښتې د پوره کولو د نذرانې، يا د رضاکارانه نذرانې يا د ستاسو په مقررو اخترونو کښې د يوې نذرانې په توګه پېش کولے شى، د دې نذرانو خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3833, 'Numbers 15:6', 'Numbers', 15, 6, '&nbsp;کله چې يو ګډ پېش کيږى، نو دوه کلو اوړۀ چې يو نيم ليټر د زيتُونو تېل ورسره ګډ وى، دا به د غلې نذرانې په توګه پېش کيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3834, 'Numbers 15:7', 'Numbers', 15, 7, '&nbsp;يو نيم ليټر مے به ورسره هم وى. د دې نذرانې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3835, 'Numbers 15:8', 'Numbers', 15, 8, '&nbsp;کله چې يو غوَيے د سوزېدونکې نذرانې په توګه يا د يوې منښتې پوره کولو د نذرانې يا د سلامتۍ د نذرانې په توګه مالِک خُدائ ته پېش کيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3836, 'Numbers 15:9', 'Numbers', 15, 9, '&nbsp;د درې کلو اوړو د غلې يوه نذرانه به پېش کيږى چې دوه ليټره د زيتُونو تېل ورسره ګډ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3837, 'Numbers 15:10', 'Numbers', 15, 10, '&nbsp;دوه ليټره مے به ورسره هم وى. د دې نذرانې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3838, 'Numbers 15:11', 'Numbers', 15, 11, '&nbsp;دا هغه څۀ دى چې د هر يو غوَيى، ګډ، ګډُورى، يا چېلۍ سره به پېش کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3839, 'Numbers 15:12', 'Numbers', 15, 12, '&nbsp;د ځناورو د شمېر په مطابق به د دې څيزونو مِقدار هم زياتولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3840, 'Numbers 15:13', 'Numbers', 15, 13, '&nbsp;د مُلک ټول اصلى پېدائشى خلق چې کله يوه په اور تيارېدونکې نذرانه پېش کوى نو هغوئ به داسې کوى، د دې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3841, 'Numbers 15:14', 'Numbers', 15, 14, '&nbsp;او کۀ ستاسو په مينځ کښې د بل مُلک کس وى، کۀ هغه د لږ وخت يا د ډېر وخت دپاره اوسېدونکے وى، نو کۀ هغوئ غواړې چې په اور تيارېدونکې نذرانه پېش کړى، چې د چا خوشبو په مالِک خُدائ ښۀ لګى، نو ضرور به هغوئ هم هغه شان اصُول منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3842, 'Numbers 15:15', 'Numbers', 15, 15, '&nbsp;په راتلونکى ټولو وختونو کښې، تاسو او ستاسو سره اوسېدونکى د بل مُلک خلق به دا اصُول منى. تاسو او هغوئ د مالِک خُدائ په نظر کښې يو شان يئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3843, 'Numbers 15:16', 'Numbers', 15, 16, '&nbsp;ستاسو او د هغوئ دپاره به يو شان قانون او اصُول وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3844, 'Numbers 15:17', 'Numbers', 15, 17, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3845, 'Numbers 15:18', 'Numbers', 15, 18, '&nbsp;چې بنى اِسرائيلو ته دا اصُول وښايه چې په هغه مُلک کښې پرې عمل کوى کوم چې مالِک خُدائ هغوئ له ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3846, 'Numbers 15:19', 'Numbers', 15, 19, '&nbsp;کله چې تاسو د هغه مُلک د فصل نه خوراک کوئ، د هغې نه به څۀ برخه مالِک خُدائ ته د خاص برخې په توګه پېش کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3847, 'Numbers 15:20', 'Numbers', 15, 20, '&nbsp;کله چې تاسو روټۍ پخوئ، نو د نوې غلې د وړومبۍ پېړې روټۍ به مالِک خُدائ ته د خاص برخې په توګه پېش کولے شى. دا به هم هغه شان پېش کولے شى چې څنګه تاسو په درمند کښې صفا شوې غله د خاص برخې په توګه پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3848, 'Numbers 15:21', 'Numbers', 15, 21, '&nbsp;په راتلونکى ټولو وختونو کښې، تاسو چې کومه روټۍ پخوئ نو دا نذرانه به مالِک خُدائ له ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3849, 'Numbers 15:22', 'Numbers', 15, 22, '&nbsp;خو کۀ څوک په غلطۍ سره په دې اصُولو باندې عمل کولو کښې ناکام شى کوم چې مالِک خُدائ موسىٰ له ورکړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3850, 'Numbers 15:23', 'Numbers', 15, 23, '&nbsp;او فرض کړئ کۀ راتلونکى نسلونه په دې هر څۀ کولو کښې ناکام شى چې مالِک خُدائ يې د موسىٰ په ذريعه حُکم کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3851, 'Numbers 15:24', 'Numbers', 15, 24, '&nbsp;کۀ يوه داسې غلطى شوې وى چې قوم ته پته نۀ وى لګېدلې، نو هغوئ به يو غوَيے د سوزېدونکې نذرانې په توګه پېش کړى، د دې خوشبو په مالِک خُدائ باندې ښۀ لګى، دا به د معيارى غلې نذرانې او د څښلو نذرانې سره پېش کيږى. د دې نه علاوه، هغوئ به يو چېلے د ګناه نذرانې په توګه هم پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3852, 'Numbers 15:25', 'Numbers', 15, 25, '&nbsp;اِمام به د قوم دپاره کفاره ادا کړى او هغوئ به معاف کړے شى، ځکه چې هغه کار په غلطۍ سره شوے وو او هغوئ خپله د ګناه نذرانه په اور تيارېدونکې نذرانې په توګه مالِک خُدائ ته راوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3853, 'Numbers 15:26', 'Numbers', 15, 26, '&nbsp;نو د بنى اِسرائيلو ټول قوم او د هغوئ سره اوسېدونکى د پردى مُلک خلق به معاف کړے شى، ځکه چې ټول په دې غلطۍ کښې شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3854, 'Numbers 15:27', 'Numbers', 15, 27, '&nbsp;کۀ يو کس په غلطۍ سره ګناه وکړى، نو هغه به د يو کال چېلۍ د ګناه نذرانې په توګه پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3855, 'Numbers 15:28', 'Numbers', 15, 28, '&nbsp;اِمام به په قربان‌ګاه باندې د هغه کس دپاره کفاره ادا کړى، چا چې په غلطۍ سره ګناه کړې وى او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3856, 'Numbers 15:29', 'Numbers', 15, 29, '&nbsp;دا اصُول د هغه هر چا دپاره يو شان دى چې څوک په غلطۍ سره ګناه وکړى، کۀ هغه په حقيقت کښې اِسرائيلے وى يا د هغوئ سره اوسېدونکے د پردى مُلک کس وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3857, 'Numbers 15:30', 'Numbers', 15, 30, '&nbsp;خو کۀ يو کس قصداً ګناه وکړى، کۀ هغه د خپل مُلک يا د پردى مُلک وى، نو د ګناه په وجه هغۀ د مالِک خُدائ بې‌عزتى کړې ده او هغه به وژلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3858, 'Numbers 15:31', 'Numbers', 15, 31, '&nbsp;ځکه چې هغۀ د مالِک خُدائ د وېنا سپکاوے کړے دے او قصداً يې د هغۀ يو حُکم مات کړے دے. نو هغه د خپل مرګ په خپله ذمه وار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3859, 'Numbers 15:32', 'Numbers', 15, 32, '&nbsp;کله چې اِسرائيليان لا په صحرا کښې وُو، نو يو سړے وليدے شو چې د سبت په ورځ يې خشاک راټولولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3860, 'Numbers 15:33', 'Numbers', 15, 33, '&nbsp;نو هغه موسىٰ، هارون او ټول قوم ته راوستلے شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3861, 'Numbers 15:34', 'Numbers', 15, 34, '&nbsp;او قېد کړے شو، ځکه چې دا پته نۀ وه چې د هغۀ سره څۀ وکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3862, 'Numbers 15:35', 'Numbers', 15, 35, '&nbsp;نو مالِک خُدائ موسىٰ ته وفرمائيل، ”هغه سړے دې خامخا ووژلے شى، ټول قوم به هغه د خېمو نه بهر سنګسار کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3863, 'Numbers 15:36', 'Numbers', 15, 36, '&nbsp;نو ټول قوم هغه د خېمو نه بهر بوتلو او سنګسار يې کړو، هم هغه شان چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3864, 'Numbers 15:37', 'Numbers', 15, 37, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3865, 'Numbers 15:38', 'Numbers', 15, 38, '&nbsp;چې، ”بنى اِسرائيلو ته ووايه، د خپلو جامو په ګوټونو باندې مزى راځوړند کړئ او په هر يو مزى باندې يې يو د آسمانى رنګ تار ولګوئ. داسې به تاسو په راتلونکى ټولو وختونو کښې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3866, 'Numbers 15:39', 'Numbers', 15, 39, '&nbsp;چې هر کله هم تاسو دا مزى ګورئ نو تاسو ته به زما ټول حُکمونه درياديږى او عمل به پرې کوئ، نو تاسو به زما نه نۀ اوړئ او د خپلو سترګو او زړۀ په خواهشونه پسې به نۀ ګرځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3867, 'Numbers 15:40', 'Numbers', 15, 40, '&nbsp;هغه مزى به تاسو ته دا دريادوى چې زما ټول حُکمونه منئ او تاسو به په پوره توګه زما يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3868, 'Numbers 15:41', 'Numbers', 15, 41, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، ما تاسو د مِصر مُلک نه راوويستلئ چې ستاسو خُدائ پاک يم. زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3869, 'Numbers 16:3', 'Numbers', 16, 3, '&nbsp;هغوئ د موسىٰ او هارون په مخکښې رابېل شول او ورته يې ووئيل، ”تاسو د حد نه تېر شوى يئ. ټول قوم د مالِک خُدائ مقدس خلق دى او مالِک خُدائ زمونږ د ټولو مل دے. نو، موسىٰ، تۀ ولې د مالِک خُدائ د قوم نه ځان اوچت ګڼې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3870, 'Numbers 16:4', 'Numbers', 16, 4, '&nbsp;کله چې موسىٰ دا واورېدل، نو هغه د خفګان نه پړمخې پرېوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3871, 'Numbers 16:5', 'Numbers', 16, 5, '&nbsp;او قورح او د هغۀ ملګرو ته يې وفرمائيل، ”مالِک خُدائ به سبا سحر مونږ ته وښائى چې څوک د هغۀ دى او څوک مقدس دى. او هغه به صِرف هغه کس خپل ځان ته نزدې پرېږدى چې کوم يې خوښ کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3872, 'Numbers 16:8', 'Numbers', 16, 8, '&nbsp;موسىٰ قورح ته وفرمائيل، ”اے ليويانو، واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3873, 'Numbers 16:9', 'Numbers', 16, 9, '&nbsp;تاسو دا وړه خبره ګڼئ چې د بنى اِسرائيلو خُدائ پاک تاسو د نور قوم نه جدا کړى يئ، چې تاسو هغۀ ته نزدې شئ، د مالِک خُدائ په خېمه کښې خِدمت وکړئ او چې د قوم مدد او خِدمت وکړئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3874, 'Numbers 16:10', 'Numbers', 16, 10, '&nbsp;هغۀ تاسو او نورو ليويانو له دا عزت درکړے دے او اوس تاسو دا وايئ چې د هغۀ اِمامان هم شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3875, 'Numbers 16:11', 'Numbers', 16, 11, '&nbsp;کله چې تاسو د هارون خِلاف غورېږئ، دا په حقيقت کښې د مالِک خُدائ خِلاف غورېدل دى او دا ستا او ستا د قبيلې سرکشى ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3876, 'Numbers 16:12', 'Numbers', 16, 12, '&nbsp;بيا موسىٰ داتن او ابيرام راوغوښتل، خو هغوئ ووئيل، ”مونږ نۀ درځُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3877, 'Numbers 16:13', 'Numbers', 16, 13, '&nbsp;دا څۀ وړه خبره ده چې مونږ تا د هغه زرخېز او آباد مُلک نه د دې دپاره راويستلى يُو چې په دې صحرا کښې مو ووژنې؟ تۀ په مونږ باندې روب اچول غواړې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3878, 'Numbers 16:14', 'Numbers', 16, 14, '&nbsp;بله دا چې تا هغه مُلک ته هم رانۀ وستلو چې زرخېز او آباد دے او نۀ دې پټى او د انګورو باغونه راکړل چې زمونږ شى. دا خلق ړاندۀ دى څۀ چې نۀ پوهيږى؟ مونږ نۀ درځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3879, 'Numbers 16:15', 'Numbers', 16, 15, '&nbsp;موسىٰ ډېر غصه شو او مالِک خُدائ ته يې وفرمائيل، ”د دوئ نذرانې مۀ قبلوه. ما دوئ يو له هم څۀ تکليف نۀ دے ورکړے، او ما د دوئ نه چرته يو خر هم نۀ دے بوتلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3880, 'Numbers 16:16', 'Numbers', 16, 16, '&nbsp;موسىٰ قورح ته وفرمائيل، ”سبا به تۀ او ستا دوه نيم سوه ملګرى خامخا د مالِک خُدائ د حضور خېمې ته راشئ، او هارون دې هم راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3881, 'Numbers 16:17', 'Numbers', 16, 17, '&nbsp;ستاسو هر يو کس به خپل مجمر واخلى، د خوشبويۍ مصالحه به په کښې واچوى او بيا به يې په قربان‌ګاه باندې پېش کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3882, 'Numbers 16:18', 'Numbers', 16, 18, '&nbsp;نو هر يو کس خپل مجمر واخستلو، ژوندى سکارۀ او د خوشبويۍ مصالحه يې په کښې واچوله او د موسىٰ او هارون سره د خېمې د دروازې په خولۀ کښې ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3883, 'Numbers 16:19', 'Numbers', 16, 19, '&nbsp;بيا قورح ټول قوم راغونډ کړو او هغوئ د خېمې د دروازې په خولۀ کښې موسىٰ او هارون ته مخامخ ودرېدل. ناڅاپه د مالِک خُدائ د حضور جلال ټول قوم ته راڅرګند شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3884, 'Numbers 16:20', 'Numbers', 16, 20, '&nbsp;او مالِک خُدائ موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3885, 'Numbers 16:21', 'Numbers', 16, 21, '&nbsp;”تاسو د دې خلقو نه لرې شئ، چې سمدستى يې تباه کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3886, 'Numbers 16:22', 'Numbers', 16, 22, '&nbsp;خو موسىٰ او هارون پړمخې پرېوتل او وې فرمائيل، ”خُدايه پاکه، ټولو خلقو له ژوند تۀ ورکوې. کله چې يو کس ګناه وکړى، نو تۀ ټولو ته په قهر کېږې څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3887, 'Numbers 16:23', 'Numbers', 16, 23, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3888, 'Numbers 16:24', 'Numbers', 16, 24, '&nbsp;”خلقو ته ووايه چې د قورح، داتن او ابيرام د خېمو نه لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3889, 'Numbers 16:25', 'Numbers', 16, 25, '&nbsp;بيا موسىٰ داتن او ابيرام له روان شو او د بنى اِسرائيلو مشران هم ورسره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3890, 'Numbers 16:26', 'Numbers', 16, 26, '&nbsp;هغۀ خلقو ته وفرمائيل، ”د دې خرابو سړو د خېمو نه لرې اوسئ او چې د هغوئ يو څيز له هم لاس ورنۀ وړئ. ګنې، د هغوئ د ټولو ګناهونو په وجه به تباه شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3891, 'Numbers 16:27', 'Numbers', 16, 27, '&nbsp;نو هغوئ د قورح، داتن او د ابيرام د خېمو نه لاړل. داتن او ابيرام بهر راوتلى وُو او د خپلو خېمو د دروازو په خُلو کښې، د خپلو ښځو سره، د خپلو بچو او د خپلو وړو ماشومانو سره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3892, 'Numbers 16:28', 'Numbers', 16, 28, '&nbsp;موسىٰ خلقو ته وفرمائيل، ”نو داسې به تاسو ته پته ولګى چې مالِک خُدائ زۀ د دې دپاره رالېږلے يم چې دا ټول کارونه وکړم او چې ما څۀ هم کړى دى نو هغه مې د ځان نه نۀ دى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3893, 'Numbers 16:29', 'Numbers', 16, 29, '&nbsp;کۀ دا سړى د خُدائ پاک د سزا نه بغېر په خپل مرګ مړۀ شى، نو بيا به مالِک خُدائ زۀ هم نۀ يم رالېږلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3894, 'Numbers 16:30', 'Numbers', 16, 30, '&nbsp;خو کۀ مالِک خُدائ يو لوئ عجيبه کار وکړى او زمکه وشليږى او هغوئ تېر کړى، چې هغوئ قبر ته ژوندى لاړ شى، نو تاسو ته به پته ولګى چې دې سړو د مالِک خُدائ سپکاوے کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3895, 'Numbers 16:31', 'Numbers', 16, 31, '&nbsp;هغۀ چې څنګه خبرې ختمې کړې، نو د داتن او ابيرام لاندې زمکه وشلېدله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3896, 'Numbers 16:32', 'Numbers', 16, 32, '&nbsp;هغوئ يې تېر کړل، د هغوئ خاندان، سره د قورح د ټولو ملګرو او چې هغوئ څۀ لرل هغه يې هم تېر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3897, 'Numbers 16:33', 'Numbers', 16, 33, '&nbsp;نو هغوئ قبر ته ژوندى لاندې لاړل، سره د هغه هر څۀ چې هغوئ لرل. زمکه په هغوئ باندې رابنده شوه او هغوئ فنا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3898, 'Numbers 16:34', 'Numbers', 16, 34, '&nbsp;هلته چې څومره اِسرائيليان وُو هغوئ چې کله د هغوئ ژړا واورېدله نو هغوئ وتښتېدل. هغوئ چغې وهلې، ”تښتئ. زمکه به مونږ هم تېر کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3899, 'Numbers 16:35', 'Numbers', 16, 35, '&nbsp;بيا مالِک خُدائ يو اور راولېږلو او هغه دوه نيم سوه سړى يې وسوزول کومو چې خوشبوئى پېش کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3900, 'Numbers 16:36', 'Numbers', 16, 36, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');